function validate([fruits, startPos, k]) {
  if (!Array.isArray(fruits) || fruits.length < 1 || fruits.length > 100000) return 'fruits needs 1 to 10^5 entries.';
  for (let i = 0; i < fruits.length; i++) {
    const entry = fruits[i];
    if (!Array.isArray(entry) || entry.length !== 2) return 'Each entry of fruits is [position, amount].';
    const [pos, amount] = entry;
    if (!Number.isInteger(pos) || pos < 0 || pos > 200000) return 'Positions are integers from 0 to 2 * 10^5.';
    if (!Number.isInteger(amount) || amount < 1 || amount > 10000) return 'Amounts are integers from 1 to 10^4.';
    if (i > 0 && fruits[i - 1][0] >= pos) return 'Positions must be strictly increasing.';
  }
  if (!Number.isInteger(startPos) || startPos < 0 || startPos > 200000) return 'startPos is between 0 and 2 * 10^5.';
  if (!Number.isInteger(k) || k < 0 || k > 200000) return 'k is between 0 and 2 * 10^5.';
  return null;
}

