function maxTotalFruits(fruits, startPos, k) {
  const steps = (leftPos, rightPos) => rightPos - leftPos + Math.min(Math.abs(startPos - leftPos), Math.abs(rightPos - startPos));
  let left = 0;
  let total = 0;
  let best = 0;

  for (let right = 0; right < fruits.length; right++) {
    total += fruits[right][1];
    while (left <= right && steps(fruits[left][0], fruits[right][0]) > k) {
      total -= fruits[left][1];
      left++;
    }
    best = Math.max(best, total);
  }
  return best;
}

