function maxTotalFruits(fruits, startPos, k) {
  // Any walk covers one interval; the best walks turn at most once. Try every turning point.
  const collect = (from, to) => {
    let sum = 0;
    for (const [pos, amount] of fruits) if (pos >= from && pos <= to) sum += amount;
    return sum;
  };
  let best = 0;
  for (let x = 0; x <= k; x++) {
    const back = Math.max(0, k - 2 * x);
    best = Math.max(best, collect(startPos - x, startPos + back));
    best = Math.max(best, collect(startPos - back, startPos + x));
  }
  return best;
}

