function generate(rand, size) {
  const limit = size === 'large' ? 200000 : 25;
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  const taken = new Set();
  while (taken.size < n) taken.add(Math.floor(rand() * (limit + 1)));
  const positions = [...taken].sort((a, b) => a - b);
  const maxAmount = size === 'large' ? 10000 : 9;
  const fruits = positions.map(pos => [pos, 1 + Math.floor(rand() * maxAmount)]);
  const startPos = Math.floor(rand() * (limit + 1));
  const reach = size === 'large' ? (rand() < 0.5 ? 20000 : 200000) : 20;
  const k = Math.floor(rand() * (reach + 1));
  return [fruits, startPos, k];
}
